def _validate_item_types(self, item_attrs: Dict[str, Any]) -> None:
    # Item attributes come in the form {attr_name: {type_tag: value}}.
    # Only the value-dicts (e.g. {"S": "..."}, {"M": {...}}) describe
    # types - the attribute names themselves can be anything, including
    # "S" or "N", so we must not interpret those as type tags.
    for value in item_attrs.values():
        self._validate_typed_value(value)

def _validate_typed_value(self, value: Any) -> None:
    if type(value) == dict:
        if len(value) == 1:
            type_tag, type_value = next(iter(value.items()))
            # This scenario is usually caught by boto3, but the user can disable parameter validation
            # Which is why we need to catch it 'server-side' as well
            if type_tag == "N" and type(type_value) == int:
                raise InvalidConversion
            if type_tag == "S":
                if type(type_value) == int:
                    raise SerializationException(
                        "NUMBER_VALUE cannot be converted to String"
                    )
                if type(type_value) == dict:
                    raise SerializationException(
                        "Start of structure or map found where not expected"
                    )
            if type_tag == "M":
                for v in type_value.values():
                    self._validate_typed_value(v)
            if type_tag == "L":
                for v in type_value:
                    self._validate_typed_value(v)
        else:
            for v in value.values():
                self._validate_typed_value(v)
    elif type(value) == list:
        for v in value:
            self._validate_typed_value(v)
